import flatpickr from "flatpickr";
import iziToast from "izitoast";

let userSelectedDate;
const startBtn = document.querySelector('button');
const dateInput = document.querySelector('#datetime-picker');
startBtn.disabled = true;
const calendar = flatpickr('#datetime-picker', {
    enableTime: true,
    time_24hr: true,
    defaultDate: new Date(),
    minuteIncrement: 1,
    onClose(selectedDates) {
        const selected = selectedDates[0];
        if (selected <= new Date()) {
            iziToast.error({
                message: "Please choose a date in the future",
                position: "topRight",
            });
            startBtn.disabled = true;
            return;
        }

        userSelectedDate = selected;
        startBtn.disabled = false;
    },
});
startBtn.addEventListener('click', () => {
    startBtn.disabled = true;
    dateInput.disabled = true;

    timer.start(userSelectedDate);
});

const timer = {
    intervalId: null,
    refs: {
        days: document.querySelector('[data-days]'),
        hours: document.querySelector('[data-hours]'),
        minutes: document.querySelector('[data-minutes]'),
        seconds: document.querySelector('[data-seconds]'),
    },

    start() {
        this.intervalId = setInterval(() => {
            const diff = userSelectedDate - Date.now();
            if (diff <= 0) {
                this.stop();
                return;
            }
            const { days, hours, minutes, seconds } = this.convertMs(diff);
            this.refs.days.textContent = this.addLeadingZero(days);
            this.refs.hours.textContent = this.addLeadingZero(hours);
            this.refs.minutes.textContent = this.addLeadingZero(minutes);
            this.refs.seconds.textContent = this.addLeadingZero(seconds);
        }, 1000);
    },

    stop() {
        clearInterval(this.intervalId);
        startBtn.disabled = false;
        dateInput.disabled = false;
    },

    convertMs(ms) {
        // Number of milliseconds per unit of time
        const second = 1000;
        const minute = second * 60;
        const hour = minute * 60;
        const day = hour * 24;

        // Remaining days
        const days = Math.floor(ms / day);
        // Remaining hours
        const hours = Math.floor((ms % day) / hour);
        // Remaining minutes
        const minutes = Math.floor(((ms % day) % hour) / minute);
        // Remaining seconds
        const seconds = Math.floor((((ms % day) % hour) % minute) / second);

        return { days, hours, minutes, seconds };
    },

    addLeadingZero(value) {
        return String(value).padStart(2, '0');
    },
};